/// <summary>
/// Simplified event subscriber abstraction.
/// </summary>
public interface IEventSubscriber<T> where T : class
{
    /// <summary>
    /// Subscribe to events with a handler.
    /// </summary>
    Task SubscribeAsync(
        Func<ConsumeContext<T>, Task> handler,
        CancellationToken cancellationToken = default);

