// EaaSClientOptionsValidator.cs
using Microsoft.Extensions.Options;
using Gainwell.EaaS.Client;

public class EaaSClientOptionsValidator : IValidateOptions<EaaSClientOptions>
{
    public ValidateOptionsResult Validate(string? name, EaaSClientOptions options)
    {
        var failures = new List<string>();

        if (string.IsNullOrWhiteSpace(options.BootstrapServers))
        {
            failures.Add("BootstrapServers is required");
        }

        if (string.IsNullOrWhiteSpace(options.Region))
        {
            failures.Add("Region is required");
        }

        if (options.RetryPolicy.MaxRetryAttempts < 0)
        {
            failures.Add("MaxRetryAttempts must be >= 0");
        }

        return failures.Any()
            ? ValidateOptionsResult.Fail(failures)
            : ValidateOptionsResult.Success;
    }
}

