// Services/ClaimService.cs
using Gainwell.EaaS.Client;

public class ClaimService
{
    private readonly IEventPublisher<ClaimApprovedEvent> _eventPublisher;
    private readonly ILogger<ClaimService> _logger;

    public ClaimService(
        IEventPublisher<ClaimApprovedEvent> eventPublisher,
        ILogger<ClaimService> logger)
    {
        _eventPublisher = eventPublisher;
        _logger = logger;
    }

    public async Task<Result> ApproveClaimAsync(
        string claimId,
        decimal amount,
        string approvedBy,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Business logic...
            var claim = await GetClaimByIdAsync(claimId, cancellationToken);
            if (claim == null)
            {
                return Result.Failure("Claim not found");
            }

            // Update claim status in database
            claim.Status = ClaimStatus.Approved;
            claim.ApprovedAmount = amount;
            claim.ApprovedDate = DateTime.UtcNow;
            claim.ApprovedBy = approvedBy;
            await SaveClaimAsync(claim, cancellationToken);

            // Publish event
            var @event = new ClaimApprovedEvent
            {
                ClaimId = claim.Id,
                MemberId = claim.MemberId,
                ApprovedAmount = amount,
                ApprovedDate = claim.ApprovedDate.Value,
                ApprovedBy = approvedBy,
                CorrelationId = Activity.Current?.Id
            };

            var result = await _eventPublisher.PublishAsync(
                @event,
                key: claim.Id,
                headers: new Dictionary<string, string>
                {
                    ["source"] = "claims-service",
                    ["event-type"] = "ClaimApproved"
                },
                cancellationToken);

            if (result.IsSuccess)
            {
                _logger.LogInformation(
                    "Published ClaimApprovedEvent for claim {ClaimId} to topic {Topic} at offset {Offset}",
                    claim.Id, result.Topic, result.Offset);
                return Result.Success();
            }
            else
            {
                _logger.LogError(result.Error,
                    "Failed to publish ClaimApprovedEvent for claim {ClaimId}",
                    claim.Id);
                return Result.Failure("Failed to publish event");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error approving claim {ClaimId}", claimId);
            return Result.Failure(ex.Message);
        }
    }
}
```

