#### Step 3.1: Create Event Handler

```csharp
// Handlers/ClaimApprovedEventHandler.cs
using Gainwell.EaaS.Client;

public class ClaimApprovedEventHandler
{
    private readonly ILogger<ClaimApprovedEventHandler> _logger;
    private readonly INotificationService _notificationService;

    public ClaimApprovedEventHandler(
        ILogger<ClaimApprovedEventHandler> logger,
        INotificationService notificationService)
    {
        _logger = logger;
        _notificationService = notificationService;
    }

    public async Task HandleAsync(
        ConsumeContext<ClaimApprovedEvent> context,
        CancellationToken cancellationToken = default)
    {
        var @event = context.Message;

        using var activity = Activity.Current?.Source.StartActivity(
            "HandleClaimApprovedEvent",
            ActivityKind.Consumer);

        activity?.SetTag("claim.id", @event.ClaimId);
        activity?.SetTag("member.id", @event.MemberId);

        try
        {
            _logger.LogInformation(
                "Processing ClaimApprovedEvent for claim {ClaimId}, member {MemberId}",
                @event.ClaimId, @event.MemberId);

            // Send notification to member
            await _notificationService.SendClaimApprovedNotificationAsync(
                @event.MemberId,
                @event.ClaimId,
                @event.ApprovedAmount,
                cancellationToken);

            // Commit offset
            await context.CommitAsync();

            _logger.LogInformation(
                "Successfully processed ClaimApprovedEvent for claim {ClaimId}",
                @event.ClaimId);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Error processing ClaimApprovedEvent for claim {ClaimId}",
                @event.ClaimId);

            // Send to DLQ after max retries
            await context.SendToDeadLetterQueueAsync(ex);
            throw;
        }
    }
}
```

