// Handlers/ClaimApprovedBatchHandler.cs
public class ClaimApprovedBatchHandler
{
    private readonly ILogger<ClaimApprovedBatchHandler> _logger;
    private readonly INotificationService _notificationService;

    public ClaimApprovedBatchHandler(
        ILogger<ClaimApprovedBatchHandler> logger,
        INotificationService notificationService)
    {
        _logger = logger;
        _notificationService = notificationService;
    }

    public async Task HandleBatchAsync(
        IEnumerable<ConsumeContext<ClaimApprovedEvent>> contexts,
        CancellationToken cancellationToken = default)
    {
        var events = contexts.ToList();
        _logger.LogInformation("Processing batch of {Count} ClaimApprovedEvents", events.Count);

        try
        {
            // Process batch in parallel
            var tasks = events.Select(async context =>
            {
                var @event = context.Message;
                await _notificationService.SendClaimApprovedNotificationAsync(
                    @event.MemberId,
                    @event.ClaimId,
                    @event.ApprovedAmount,
                    cancellationToken);
            });

            await Task.WhenAll(tasks);

            // Commit all offsets
            foreach (var context in events)
            {
                await context.CommitAsync();
            }

            _logger.LogInformation(
                "Successfully processed batch of {Count} ClaimApprovedEvents",
                events.Count);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error processing ClaimApprovedEvent batch");

            // Send failed messages to DLQ
            foreach (var context in events)
            {
                await context.SendToDeadLetterQueueAsync(ex);
            }

            throw;
        }
    }
}

// Register batch subscriber
builder.Services.AddEventSubscriber<ClaimApprovedEvent>(options =>
{
    options.Topic = "claims.approved.v1";
    options.GroupId = "notification-service-batch";
    options.EnableAutoCommit = false;
    options.EnableBatchProcessing = true;
    options.BatchSize = 100;
    options.BatchWaitTime = TimeSpan.FromSeconds(5);
});

// Start batch subscriber
_ = Task.Run(async () =>
{
    await subscriber.SubscribeBatchAsync(
        handler.HandleBatchAsync,
        app.Lifetime.ApplicationStopping);
});
```

