#### Step 4.3: Use Outbox Publisher

```csharp
// Services/ClaimService.cs (with transactional outbox)
using Gainwell.EaaS.Client;
using Microsoft.EntityFrameworkCore.Storage;

public class ClaimService
{
    private readonly ClaimsDbContext _dbContext;
    private readonly ITransactionalOutboxPublisher<ClaimApprovedEvent> _outboxPublisher;
    private readonly ILogger<ClaimService> _logger;

    public ClaimService(
        ClaimsDbContext dbContext,
        ITransactionalOutboxPublisher<ClaimApprovedEvent> outboxPublisher,
        ILogger<ClaimService> logger)
    {
        _dbContext = dbContext;
        _outboxPublisher = outboxPublisher;
        _logger = logger;
    }

    public async Task<Result> ApproveClaimAsync(
        string claimId,
        decimal amount,
        string approvedBy,
        CancellationToken cancellationToken = default)
    {
        // Begin database transaction
        await using var transaction = await _dbContext.Database.BeginTransactionAsync(
            cancellationToken);

        try
        {
            // Update claim in database
            var claim = await _dbContext.Claims
                .FirstOrDefaultAsync(c => c.Id == claimId, cancellationToken);

            if (claim == null)
            {
                return Result.Failure("Claim not found");
            }

            claim.Status = ClaimStatus.Approved;
            claim.ApprovedAmount = amount;
            claim.ApprovedDate = DateTime.UtcNow;
            claim.ApprovedBy = approvedBy;

            await _dbContext.SaveChangesAsync(cancellationToken);

            // Publish event to outbox (same transaction)
            var @event = new ClaimApprovedEvent
            {
                ClaimId = claim.Id,
                MemberId = claim.MemberId,
                ApprovedAmount = amount,
                ApprovedDate = claim.ApprovedDate.Value,
                ApprovedBy = approvedBy,
                CorrelationId = Activity.Current?.Id
            };

            await _outboxPublisher.PublishAsync(
                @event,
                transaction: transaction.GetDbTransaction(),
                key: claim.Id,
                headers: new Dictionary<string, string>
                {
                    ["source"] = "claims-service",
                    ["event-type"] = "ClaimApproved"
                },
                cancellationToken);

            // Commit transaction (both claim update and outbox entry)
            await transaction.CommitAsync(cancellationToken);

            _logger.LogInformation(
                "Approved claim {ClaimId} and added event to outbox",
                claim.Id);

            return Result.Success();
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync(cancellationToken);
            _logger.LogError(ex, "Error approving claim {ClaimId}", claimId);
            return Result.Failure(ex.Message);
        }
    }
}
```

**Note**: The SDK's background service automatically polls the outbox table and publishes pending events to Kafka. No additional code is required.

