#### Example 1: Simple Event Publisher

```csharp
// Events/OrderPlacedEvent.cs
public record OrderPlacedEvent
{
    public required string OrderId { get; init; }
    public required string CustomerId { get; init; }
    public required decimal TotalAmount { get; init; }
    public required DateTime OrderDate { get; init; }
    public required List<OrderLineItem> Items { get; init; }
}

public record OrderLineItem
{
    public required string ProductId { get; init; }
    public required int Quantity { get; init; }
    public required decimal Price { get; init; }
}

// Services/OrderService.cs
using Gainwell.EaaS.Client;

public class OrderService
{
    private readonly IEventPublisher<OrderPlacedEvent> _eventPublisher;
    private readonly IOrderRepository _repository;
    private readonly ILogger<OrderService> _logger;

    public OrderService(
        IEventPublisher<OrderPlacedEvent> eventPublisher,
        IOrderRepository repository,
        ILogger<OrderService> logger)
    {
        _eventPublisher = eventPublisher;
        _repository = repository;
        _logger = logger;
    }

    public async Task<Result<string>> PlaceOrderAsync(
        PlaceOrderCommand command,
        CancellationToken cancellationToken = default)
    {
        try
        {
            // Create order
            var order = new Order
            {
                Id = Guid.NewGuid().ToString(),
                CustomerId = command.CustomerId,
                OrderDate = DateTime.UtcNow,
                Items = command.Items.Select(i => new OrderLineItem
                {
                    ProductId = i.ProductId,
                    Quantity = i.Quantity,
                    Price = i.Price
                }).ToList()
            };

            order.TotalAmount = order.Items.Sum(i => i.Price * i.Quantity);

            // Save to database
            await _repository.SaveAsync(order, cancellationToken);

            // Publish event
            var @event = new OrderPlacedEvent
            {
                OrderId = order.Id,
                CustomerId = order.CustomerId,
                TotalAmount = order.TotalAmount,
                OrderDate = order.OrderDate,
                Items = order.Items
            };

            var publishResult = await _eventPublisher.PublishAsync(
                @event,
                key: order.CustomerId, // Partition by customer
                headers: new Dictionary<string, string>
                {
                    ["event-source"] = "order-service",
                    ["event-type"] = "OrderPlaced",
                    ["correlation-id"] = Activity.Current?.Id ?? Guid.NewGuid().ToString()
                },
                cancellationToken);

            if (publishResult.IsSuccess)
            {
                _logger.LogInformation(
                    "Published OrderPlacedEvent for order {OrderId} at offset {Offset}",
                    order.Id, publishResult.Offset);

                return Result<string>.Success(order.Id);
            }
            else
            {
                _logger.LogError(publishResult.Error,
                    "Failed to publish OrderPlacedEvent for order {OrderId}",
                    order.Id);

                return Result<string>.Failure("Failed to publish event");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error placing order for customer {CustomerId}",
                command.CustomerId);
            return Result<string>.Failure(ex.Message);
        }
    }
}

// Program.cs
builder.Services.AddEventPublisher<OrderPlacedEvent>(options =>
{
    options.Topic = "orders.placed.v1";
    options.KeySelector = evt => evt.CustomerId;
    options.EnableSchemaValidation = true;
});
```

