#### Example 2: Event Subscriber with Retry Logic

```csharp
// Handlers/OrderPlacedEventHandler.cs
using Gainwell.EaaS.Client;
using Polly;
using Polly.CircuitBreaker;

public class OrderPlacedEventHandler
{
    private readonly IInventoryService _inventoryService;
    private readonly ILogger<OrderPlacedEventHandler> _logger;
    private readonly IAsyncPolicy _retryPolicy;

    public OrderPlacedEventHandler(
        IInventoryService inventoryService,
        ILogger<OrderPlacedEventHandler> logger)
    {
        _inventoryService = inventoryService;
        _logger = logger;

        // Custom retry policy with circuit breaker
        _retryPolicy = Policy
            .Handle<HttpRequestException>()
            .Or<TimeoutException>()
            .WaitAndRetryAsync(
                retryCount: 3,
                sleepDurationProvider: attempt => TimeSpan.FromSeconds(Math.Pow(2, attempt)),
                onRetry: (exception, timeSpan, retryCount, context) =>
                {
                    _logger.LogWarning(
                        "Retry {RetryCount} after {Delay}s due to {Exception}",
                        retryCount, timeSpan.TotalSeconds, exception.GetType().Name);
                })
            .WrapAsync(Policy
                .Handle<HttpRequestException>()
                .CircuitBreakerAsync(
                    handledEventsAllowedBeforeBreaking: 5,
                    durationOfBreak: TimeSpan.FromMinutes(1),
                    onBreak: (exception, duration) =>
                    {
                        _logger.LogError(
                            "Circuit breaker opened for {Duration}s",
                            duration.TotalSeconds);
                    },
                    onReset: () => _logger.LogInformation("Circuit breaker reset")));
    }

    public async Task HandleAsync(
        ConsumeContext<OrderPlacedEvent> context,
        CancellationToken cancellationToken = default)
    {
        var @event = context.Message;

        using var activity = Activity.Current?.Source.StartActivity(
            "HandleOrderPlacedEvent",
            ActivityKind.Consumer);

        activity?.SetTag("order.id", @event.OrderId);
        activity?.SetTag("customer.id", @event.CustomerId);
        activity?.SetTag("order.total", @event.TotalAmount);

        try
        {
            _logger.LogInformation(
                "Processing OrderPlacedEvent for order {OrderId}, customer {CustomerId}",
                @event.OrderId, @event.CustomerId);

            // Reserve inventory with retry policy
            await _retryPolicy.ExecuteAsync(async () =>
            {
                foreach (var item in @event.Items)
                {
                    await _inventoryService.ReserveInventoryAsync(
                        item.ProductId,
                        item.Quantity,
                        @event.OrderId,
                        cancellationToken);

                    _logger.LogInformation(
                        "Reserved {Quantity} units of product {ProductId} for order {OrderId}",
                        item.Quantity, item.ProductId, @event.OrderId);
                }
            });

            // Commit offset on success
            await context.CommitAsync();

            _logger.LogInformation(
                "Successfully processed OrderPlacedEvent for order {OrderId}",
                @event.OrderId);
        }
        catch (BrokenCircuitException ex)
        {
            _logger.LogError(ex,
                "Circuit breaker open - cannot process OrderPlacedEvent for order {OrderId}",
                @event.OrderId);

            // Don't send to DLQ immediately; let Kafka redelivery handle it
            throw;
        }
        catch (Exception ex)
        {
            _logger.LogError(ex,
                "Error processing OrderPlacedEvent for order {OrderId}",
                @event.OrderId);

            // Send to DLQ after retries exhausted
            await context.SendToDeadLetterQueueAsync(ex);
        }
    }
}

// Program.cs
builder.Services.AddEventSubscriber<OrderPlacedEvent>(options =>
{
    options.Topic = "orders.placed.v1";
    options.GroupId = "inventory-service";
    options.EnableAutoCommit = false;
});

builder.Services.AddSingleton<OrderPlacedEventHandler>();

var app = builder.Build();

var subscriber = app.Services.GetRequiredService<IEventSubscriber<OrderPlacedEvent>>();
var handler = app.Services.GetRequiredService<OrderPlacedEventHandler>();

_ = Task.Run(async () =>
{
    await subscriber.SubscribeAsync(
        handler.HandleAsync,
        app.Lifetime.ApplicationStopping);
});

app.Run();
```

