public class OrderService
{
    private readonly OrdersDbContext _dbContext;
    private readonly ITransactionalOutboxPublisher<OrderPlacedEvent> _outboxPublisher;
    private readonly ILogger<OrderService> _logger;

    public OrderService(
        OrdersDbContext dbContext,
        ITransactionalOutboxPublisher<OrderPlacedEvent> outboxPublisher,
        ILogger<OrderService> logger)
    {
        _dbContext = dbContext;
        _outboxPublisher = outboxPublisher;
        _logger = logger;
    }

    public async Task<Result<string>> PlaceOrderAsync(
        PlaceOrderCommand command,
        CancellationToken cancellationToken = default)
    {
        // Start transaction
        await using var transaction = await _dbContext.Database.BeginTransactionAsync(
            cancellationToken);

        try
        {
            // Create and save order
            var order = new Order
            {
                Id = Guid.NewGuid().ToString(),
                CustomerId = command.CustomerId,
                OrderDate = DateTime.UtcNow,
                Items = command.Items.Select(i => new OrderLineItem
                {
                    ProductId = i.ProductId,
                    Quantity = i.Quantity,
                    Price = i.Price
                }).ToList()
            };

            order.TotalAmount = order.Items.Sum(i => i.Price * i.Quantity);

            _dbContext.Orders.Add(order);
            await _dbContext.SaveChangesAsync(cancellationToken);

            // Add event to outbox (same transaction)
            var @event = new OrderPlacedEvent
            {
                OrderId = order.Id,
                CustomerId = order.CustomerId,
                TotalAmount = order.TotalAmount,
                OrderDate = order.OrderDate,
                Items = order.Items
            };

            await _outboxPublisher.PublishAsync(
                @event,
                transaction: transaction.GetDbTransaction(),
                key: order.CustomerId,
                headers: new Dictionary<string, string>
                {
                    ["event-source"] = "order-service",
                    ["event-type"] = "OrderPlaced"
                },
                cancellationToken);

            // Commit transaction (order + outbox entry)
            await transaction.CommitAsync(cancellationToken);

            _logger.LogInformation(
                "Created order {OrderId} and added event to outbox",
                order.Id);

            return Result<string>.Success(order.Id);
        }
        catch (Exception ex)
        {
            await transaction.RollbackAsync(cancellationToken);
            _logger.LogError(ex, "Error placing order for customer {CustomerId}",
                command.CustomerId);
            return Result<string>.Failure(ex.Message);
        }
    }
}

