#### Example 4: Batch Event Processing

```csharp
// Handlers/OrderPlacedBatchHandler.cs
using Gainwell.EaaS.Client;
using System.Collections.Concurrent;

public class OrderPlacedBatchHandler
{
    private readonly IInventoryService _inventoryService;
    private readonly ILogger<OrderPlacedBatchHandler> _logger;

    public OrderPlacedBatchHandler(
        IInventoryService inventoryService,
        ILogger<OrderPlacedBatchHandler> logger)
    {
        _inventoryService = inventoryService;
        _logger = logger;
    }

    public async Task HandleBatchAsync(
        IEnumerable<ConsumeContext<OrderPlacedEvent>> contexts,
        CancellationToken cancellationToken = default)
    {
        var batch = contexts.ToList();
        _logger.LogInformation("Processing batch of {Count} OrderPlacedEvents", batch.Count);

        using var activity = Activity.Current?.Source.StartActivity(
            "HandleOrderPlacedEventBatch",
            ActivityKind.Consumer);

        activity?.SetTag("batch.size", batch.Count);

        var successfulContexts = new ConcurrentBag<ConsumeContext<OrderPlacedEvent>>();
        var failedContexts = new ConcurrentBag<(ConsumeContext<OrderPlacedEvent>, Exception)>();

        try
        {
            // Process batch in parallel with semaphore for concurrency control
            var semaphore = new SemaphoreSlim(10); // Max 10 concurrent
            var tasks = batch.Select(async context =>
            {
                await semaphore.WaitAsync(cancellationToken);
                try
                {
                    var @event = context.Message;

                    // Reserve inventory for each item
                    foreach (var item in @event.Items)
                    {
                        await _inventoryService.ReserveInventoryAsync(
                            item.ProductId,
                            item.Quantity,
                            @event.OrderId,
                            cancellationToken);
                    }

                    successfulContexts.Add(context);

                    _logger.LogDebug(
                        "Successfully processed order {OrderId} in batch",
                        @event.OrderId);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex,
                        "Error processing order {OrderId} in batch",
                        context.Message.OrderId);

                    failedContexts.Add((context, ex));
                }
                finally
                {
                    semaphore.Release();
                }
            });

            await Task.WhenAll(tasks);

            // Commit successful offsets
            foreach (var context in successfulContexts)
            {
                await context.CommitAsync();
            }

            // Send failed messages to DLQ
            foreach (var (context, exception) in failedContexts)
            {
                await context.SendToDeadLetterQueueAsync(exception);
            }

            _logger.LogInformation(
                "Batch processing complete: {SuccessCount} successful, {FailCount} failed",
                successfulContexts.Count, failedContexts.Count);

            activity?.SetTag("batch.success.count", successfulContexts.Count);
            activity?.SetTag("batch.fail.count", failedContexts.Count);
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Critical error during batch processing");

            // Send all to DLQ on critical failure
            foreach (var context in batch)
            {
                await context.SendToDeadLetterQueueAsync(ex);
            }

            throw;
        }
    }
}

// Program.cs
builder.Services.AddEventSubscriber<OrderPlacedEvent>(options =>
{
    options.Topic = "orders.placed.v1";
    options.GroupId = "inventory-service-batch";
    options.EnableAutoCommit = false;
    options.EnableBatchProcessing = true;
    options.BatchSize = 100;
    options.BatchWaitTime = TimeSpan.FromSeconds(5);
    options.EnableAdaptiveSizing = true; // SDK adjusts batch size dynamically
});

builder.Services.AddSingleton<OrderPlacedBatchHandler>();

var app = builder.Build();

var subscriber = app.Services.GetRequiredService<IEventSubscriber<OrderPlacedEvent>>();
var handler = app.Services.GetRequiredService<OrderPlacedBatchHandler>();

