#### Example 5: Custom Retry Policy Configuration

```csharp
// Program.cs - Per-event-type retry configuration
builder.Services.AddEventPublisher<CriticalEvent>(options =>
{
    options.Topic = "critical.events.v1";

    // Custom retry policy for critical events
    options.RetryPolicy.MaxRetryAttempts = 5;
    options.RetryPolicy.InitialDelay = TimeSpan.FromSeconds(2);
    options.RetryPolicy.MaxDelay = TimeSpan.FromMinutes(2);
    options.RetryPolicy.BackoffMultiplier = 2.5;
    options.RetryPolicy.UseJitter = true;

    // Only retry on specific exceptions
    options.RetryPolicy.RetryableExceptions.Add(typeof(KafkaBrokerNotAvailableException));
    options.RetryPolicy.RetryableExceptions.Add(typeof(KafkaTimeoutException));

    // Never retry these
    options.RetryPolicy.NonRetryableExceptions.Add(typeof(SerializationException));
    options.RetryPolicy.NonRetryableExceptions.Add(typeof(SchemaValidationException));
});

builder.Services.AddEventPublisher<NonCriticalEvent>(options =>
{
    options.Topic = "non-critical.events.v1";

    // Fewer retries for non-critical events
    options.RetryPolicy.MaxRetryAttempts = 2;
    options.RetryPolicy.InitialDelay = TimeSpan.FromMilliseconds(500);
    options.RetryPolicy.MaxDelay = TimeSpan.FromSeconds(10);
});
